import React, { useMemo, useState } from 'react';
import { AnimatePresence, motion } from 'motion/react';
import { Check, ChevronUp, Search, Settings, X, type LucideIcon } from 'lucide-react';

export interface MobileWorkspaceSectionItem {
  id: string;
  label: string;
  icon: LucideIcon;
  category?: string;
}

interface MobileWorkspaceSectionNavProps {
  title: string;
  items: MobileWorkspaceSectionItem[];
  activeView: string;
  onNavigate: (view: string) => void;
  onOpenSettings: () => void;
  accent: 'emerald' | 'indigo';
}

const accentClasses = {
  emerald: {
    icon: 'text-emerald-300',
    active: 'border-emerald-400/35 bg-emerald-400/10',
    focus: 'focus:border-emerald-400/50',
  },
  indigo: {
    icon: 'text-indigo-300',
    active: 'border-indigo-400/35 bg-indigo-400/10',
    focus: 'focus:border-indigo-400/50',
  },
} as const;

export const MobileWorkspaceSectionNav: React.FC<MobileWorkspaceSectionNavProps> = ({
  title,
  items,
  activeView,
  onNavigate,
  onOpenSettings,
  accent,
}) => {
  const [isOpen, setIsOpen] = useState(false);
  const [query, setQuery] = useState('');
  const classes = accentClasses[accent];
  const activeItem = items.find((item) => item.id === activeView) ?? items[0];
  const filteredItems = useMemo(() => {
    const normalizedQuery = query.trim().toLowerCase();
    if (!normalizedQuery) return items;
    return items.filter((item) => (
      item.label.toLowerCase().includes(normalizedQuery)
      || item.category?.toLowerCase().includes(normalizedQuery)
    ));
  }, [items, query]);

  const selectView = (view: string) => {
    onNavigate(view);
    setIsOpen(false);
    setQuery('');
  };

  const ActiveIcon = activeItem?.icon;

  return (
    <>
      <div className="md:hidden shrink-0 border-b border-white/[0.06] bg-[#0A0A0A]/95 px-3 py-2 backdrop-blur-xl">
        <div className="flex min-w-0 items-center gap-2">
          <button
            type="button"
            onClick={() => setIsOpen(true)}
            className="flex min-w-0 flex-1 items-center gap-2.5 rounded-full border border-white/10 bg-white/[0.04] px-3.5 py-2.5 text-left text-white transition-colors active:bg-white/[0.08]"
            aria-haspopup="dialog"
            aria-expanded={isOpen}
          >
            {ActiveIcon && <ActiveIcon className={`h-4 w-4 shrink-0 ${classes.icon}`} />}
            <span className="min-w-0 flex-1 truncate text-sm font-semibold">
              <span className="text-gray-500">{title}</span>
              <span className="mx-1.5 text-gray-700">/</span>
              {activeItem?.label ?? 'Tools'}
            </span>
            <ChevronUp className="h-4 w-4 shrink-0 text-gray-500" />
          </button>
          <button
            type="button"
            onClick={onOpenSettings}
            className="grid h-10 w-10 shrink-0 place-items-center rounded-full border border-white/10 text-gray-400 transition-colors hover:bg-white/[0.06] hover:text-white active:bg-white/10"
            aria-label={`${title} settings`}
            aria-haspopup="dialog"
          >
            <Settings className="h-4 w-4" />
          </button>
        </div>
      </div>

      <AnimatePresence>
        {isOpen && (
          <>
            <motion.button
              type="button"
              aria-label="Close tools"
              className="fixed inset-0 z-[86] bg-black/65 backdrop-blur-[2px] md:hidden"
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              onClick={() => setIsOpen(false)}
            />
            <motion.section
              role="dialog"
              aria-modal="true"
              aria-label={`${title} tools`}
              className="fixed inset-x-3 bottom-[calc(82px+env(safe-area-inset-bottom))] z-[87] flex max-h-[min(68dvh,620px)] flex-col overflow-hidden rounded-[28px] border border-white/10 bg-[#111111] shadow-2xl md:hidden"
              initial={{ opacity: 0, y: 28, scale: 0.98 }}
              animate={{ opacity: 1, y: 0, scale: 1 }}
              exit={{ opacity: 0, y: 22, scale: 0.98 }}
              transition={{ type: 'spring', stiffness: 360, damping: 32 }}
            >
              <div className="flex items-center gap-3 border-b border-white/[0.07] px-4 py-3.5">
                <div className="min-w-0 flex-1">
                  <p className="text-[10px] font-black uppercase tracking-[0.18em] text-gray-500">{title}</p>
                  <h2 className="truncate text-base font-bold text-white">Choose a tool</h2>
                </div>
                <button
                  type="button"
                  onClick={() => setIsOpen(false)}
                  className="grid h-9 w-9 place-items-center rounded-full border border-white/10 text-gray-400 transition-colors hover:text-white"
                  aria-label="Close"
                >
                  <X className="h-4 w-4" />
                </button>
              </div>

              <div className="px-4 pb-2 pt-3">
                <label className="relative block">
                  <Search className="pointer-events-none absolute left-3.5 top-1/2 h-4 w-4 -translate-y-1/2 text-gray-500" />
                  <input
                    type="search"
                    value={query}
                    onChange={(event) => setQuery(event.target.value)}
                    placeholder={`Search ${title.toLowerCase()} tools`}
                    className={`w-full rounded-full border border-white/10 bg-white/[0.04] py-2.5 pl-10 pr-4 text-sm text-white outline-none placeholder:text-gray-600 ${classes.focus}`}
                    autoFocus
                  />
                </label>
              </div>

              <div className="min-h-0 flex-1 overflow-y-auto overscroll-contain px-3 pb-4 pt-1">
                {filteredItems.length > 0 ? (
                  <div className="grid grid-cols-1 gap-1">
                    {filteredItems.map((item) => {
                      const Icon = item.icon;
                      const isActive = item.id === activeView;
                      return (
                        <button
                          type="button"
                          key={item.id}
                          onClick={() => selectView(item.id)}
                          className={`flex min-h-12 w-full items-center gap-3 rounded-2xl border px-3.5 py-2.5 text-left transition-colors ${
                            isActive
                              ? `${classes.active} text-white`
                              : 'border-transparent text-gray-300 hover:bg-white/[0.05]'
                          }`}
                          aria-current={isActive ? 'page' : undefined}
                        >
                          <span className="grid h-8 w-8 shrink-0 place-items-center rounded-full bg-white/[0.05]">
                            <Icon className={`h-4 w-4 ${isActive ? classes.icon : 'text-gray-500'}`} />
                          </span>
                          <span className="min-w-0 flex-1 truncate text-sm font-semibold">{item.label}</span>
                          {isActive && <Check className={`h-4 w-4 shrink-0 ${classes.icon}`} />}
                        </button>
                      );
                    })}
                  </div>
                ) : (
                  <div className="px-4 py-10 text-center text-sm text-gray-500">No matching tools.</div>
                )}
              </div>
            </motion.section>
          </>
        )}
      </AnimatePresence>
    </>
  );
};
