import { useEffect, useRef, useState, type KeyboardEvent, type PointerEvent } from 'react';
import { Check, ChevronDown, Pipette } from 'lucide-react';

interface CustomColorPickerProps {
  id: string;
  label: string;
  value: string;
  onChange: (value: string) => void;
  description?: string;
  swatches?: readonly string[];
}

interface HsvColor {
  h: number;
  s: number;
  v: number;
}

interface EyeDropperResult {
  sRGBHex: string;
}

interface EyeDropperInstance {
  open: () => Promise<EyeDropperResult>;
}

type EyeDropperConstructor = new () => EyeDropperInstance;

const DEFAULT_COLOR = '#000000';
const DEFAULT_SWATCHES = [
  '#0A0A0A',
  '#FFFFFF',
  '#635BFF',
  '#2563EB',
  '#06B6D4',
  '#10B981',
  '#F59E0B',
  '#F43F5E',
  '#A855F7',
  '#EC4899',
] as const;

const clamp = (value: number, min: number, max: number) => Math.min(Math.max(value, min), max);

const normalizeHex = (value: string): string | null => {
  const trimmed = value.trim();
  const shorthand = /^#?([\dA-F])([\dA-F])([\dA-F])$/i.exec(trimmed);

  if (shorthand) {
    return `#${shorthand[1]}${shorthand[1]}${shorthand[2]}${shorthand[2]}${shorthand[3]}${shorthand[3]}`.toUpperCase();
  }

  const full = /^#?([\dA-F]{6})$/i.exec(trimmed);
  return full ? `#${full[1].toUpperCase()}` : null;
};

const hexToHsv = (hex: string): HsvColor => {
  const normalized = normalizeHex(hex) ?? DEFAULT_COLOR;
  const red = Number.parseInt(normalized.slice(1, 3), 16) / 255;
  const green = Number.parseInt(normalized.slice(3, 5), 16) / 255;
  const blue = Number.parseInt(normalized.slice(5, 7), 16) / 255;
  const max = Math.max(red, green, blue);
  const min = Math.min(red, green, blue);
  const delta = max - min;

  let hue = 0;
  if (delta !== 0) {
    if (max === red) {
      hue = 60 * (((green - blue) / delta) % 6);
    } else if (max === green) {
      hue = 60 * ((blue - red) / delta + 2);
    } else {
      hue = 60 * ((red - green) / delta + 4);
    }
  }

  return {
    h: hue < 0 ? hue + 360 : hue,
    s: max === 0 ? 0 : (delta / max) * 100,
    v: max * 100,
  };
};

const hsvToHex = ({ h, s, v }: HsvColor): string => {
  const saturation = clamp(s, 0, 100) / 100;
  const brightness = clamp(v, 0, 100) / 100;
  const chroma = brightness * saturation;
  const hueSection = ((h % 360) + 360) % 360 / 60;
  const x = chroma * (1 - Math.abs((hueSection % 2) - 1));
  const match = brightness - chroma;

  let red = 0;
  let green = 0;
  let blue = 0;

  if (hueSection < 1) {
    [red, green, blue] = [chroma, x, 0];
  } else if (hueSection < 2) {
    [red, green, blue] = [x, chroma, 0];
  } else if (hueSection < 3) {
    [red, green, blue] = [0, chroma, x];
  } else if (hueSection < 4) {
    [red, green, blue] = [0, x, chroma];
  } else if (hueSection < 5) {
    [red, green, blue] = [x, 0, chroma];
  } else {
    [red, green, blue] = [chroma, 0, x];
  }

  const toHexChannel = (channel: number) =>
    Math.round((channel + match) * 255).toString(16).padStart(2, '0');

  return `#${toHexChannel(red)}${toHexChannel(green)}${toHexChannel(blue)}`.toUpperCase();
};

const isLightColor = (hex: string) => {
  const normalized = normalizeHex(hex) ?? DEFAULT_COLOR;
  const red = Number.parseInt(normalized.slice(1, 3), 16);
  const green = Number.parseInt(normalized.slice(3, 5), 16);
  const blue = Number.parseInt(normalized.slice(5, 7), 16);
  return (red * 299 + green * 587 + blue * 114) / 1000 > 155;
};

export function CustomColorPicker({
  id,
  label,
  value,
  onChange,
  description,
  swatches = DEFAULT_SWATCHES,
}: CustomColorPickerProps) {
  const [isOpen, setIsOpen] = useState(false);
  const normalizedColor = normalizeHex(value) ?? DEFAULT_COLOR;
  const [hexDraft, setHexDraft] = useState(normalizedColor);
  const rootRef = useRef<HTMLDivElement>(null);
  const hsv = hexToHsv(normalizedColor);
  const canUseEyeDropper =
    typeof window !== 'undefined' &&
    Boolean((window as Window & { EyeDropper?: EyeDropperConstructor }).EyeDropper);

  useEffect(() => {
    setHexDraft(normalizedColor);
  }, [normalizedColor]);

  useEffect(() => {
    if (!isOpen) return;

    const handlePointerDown = (event: globalThis.PointerEvent) => {
      if (!rootRef.current?.contains(event.target as Node)) {
        setIsOpen(false);
      }
    };

    const handleKeyDown = (event: globalThis.KeyboardEvent) => {
      if (event.key === 'Escape') {
        setIsOpen(false);
      }
    };

    document.addEventListener('pointerdown', handlePointerDown);
    document.addEventListener('keydown', handleKeyDown);

    return () => {
      document.removeEventListener('pointerdown', handlePointerDown);
      document.removeEventListener('keydown', handleKeyDown);
    };
  }, [isOpen]);

  const commitColor = (nextColor: string) => {
    const normalized = normalizeHex(nextColor);
    if (!normalized) return;

    setHexDraft(normalized);
    onChange(normalized);
  };

  const updateSaturationAndBrightness = (event: PointerEvent<HTMLDivElement>) => {
    const bounds = event.currentTarget.getBoundingClientRect();
    const saturation = clamp((event.clientX - bounds.left) / bounds.width, 0, 1) * 100;
    const brightness = (1 - clamp((event.clientY - bounds.top) / bounds.height, 0, 1)) * 100;
    commitColor(hsvToHex({ h: hsv.h, s: saturation, v: brightness }));
  };

  const handleSaturationPointerDown = (event: PointerEvent<HTMLDivElement>) => {
    event.currentTarget.setPointerCapture(event.pointerId);
    updateSaturationAndBrightness(event);
  };

  const handleSaturationPointerMove = (event: PointerEvent<HTMLDivElement>) => {
    if (event.currentTarget.hasPointerCapture(event.pointerId)) {
      updateSaturationAndBrightness(event);
    }
  };

  const updateHue = (event: PointerEvent<HTMLDivElement>) => {
    const bounds = event.currentTarget.getBoundingClientRect();
    const hue = clamp((event.clientX - bounds.left) / bounds.width, 0, 1) * 360;
    commitColor(hsvToHex({ ...hsv, h: hue }));
  };

  const handleHuePointerDown = (event: PointerEvent<HTMLDivElement>) => {
    event.currentTarget.setPointerCapture(event.pointerId);
    updateHue(event);
  };

  const handleHuePointerMove = (event: PointerEvent<HTMLDivElement>) => {
    if (event.currentTarget.hasPointerCapture(event.pointerId)) {
      updateHue(event);
    }
  };

  const handleSaturationKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    const step = event.shiftKey ? 10 : 2;
    const nextColor = { ...hsv };

    if (event.key === 'ArrowLeft') nextColor.s -= step;
    else if (event.key === 'ArrowRight') nextColor.s += step;
    else if (event.key === 'ArrowDown') nextColor.v -= step;
    else if (event.key === 'ArrowUp') nextColor.v += step;
    else return;

    event.preventDefault();
    commitColor(hsvToHex(nextColor));
  };

  const handleHueKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    const step = event.shiftKey ? 10 : 2;

    if (event.key === 'ArrowLeft' || event.key === 'ArrowDown') {
      event.preventDefault();
      commitColor(hsvToHex({ ...hsv, h: hsv.h - step }));
    } else if (event.key === 'ArrowRight' || event.key === 'ArrowUp') {
      event.preventDefault();
      commitColor(hsvToHex({ ...hsv, h: hsv.h + step }));
    }
  };

  const handleHexChange = (nextDraft: string) => {
    const sanitized = `#${nextDraft.replace(/#/g, '').replace(/[^\dA-F]/gi, '').slice(0, 6).toUpperCase()}`;
    setHexDraft(sanitized);

    if (sanitized.length === 7) {
      commitColor(sanitized);
    }
  };

  const handleEyeDropper = async () => {
    const EyeDropperApi = (window as Window & { EyeDropper?: EyeDropperConstructor }).EyeDropper;
    if (!EyeDropperApi) return;

    try {
      const result = await new EyeDropperApi().open();
      commitColor(result.sRGBHex);
    } catch (error) {
      if (!(error instanceof DOMException && error.name === 'AbortError')) {
        console.error('Unable to sample color from the screen.', error);
      }
    }
  };

  return (
    <div ref={rootRef} className="relative">
      <div className="mb-2 flex items-start justify-between gap-3">
        <div>
          <span id={`${id}-label`} className="block text-xs font-semibold text-gray-300">
            {label}
          </span>
          {description && <p className="mt-0.5 text-[10px] leading-4 text-gray-500">{description}</p>}
        </div>
        <span className="font-mono text-[10px] uppercase tracking-wide text-gray-500">{normalizedColor}</span>
      </div>

      <button
        type="button"
        aria-expanded={isOpen}
        aria-controls={`${id}-panel`}
        aria-labelledby={`${id}-label`}
        onClick={() => setIsOpen((current) => !current)}
        className={`flex w-full items-center gap-3 rounded-xl border px-3 py-2.5 text-left transition ${
          isOpen
            ? 'border-[#635BFF]/70 bg-[#635BFF]/10 shadow-[0_0_0_3px_rgba(99,91,255,0.08)]'
            : 'border-white/10 bg-white/[0.035] hover:border-white/20 hover:bg-white/[0.06]'
        }`}
      >
        <span
          className="h-9 w-9 shrink-0 rounded-lg border border-white/15 shadow-[inset_0_0_0_1px_rgba(0,0,0,0.2),0_4px_12px_rgba(0,0,0,0.25)]"
          style={{ backgroundColor: normalizedColor }}
        />
        <span className="min-w-0 flex-1">
          <span className="block text-xs font-medium text-white">Choose color</span>
          <span className="block truncate font-mono text-[10px] text-gray-500">{normalizedColor}</span>
        </span>
        <ChevronDown
          aria-hidden="true"
          className={`h-4 w-4 text-gray-500 transition-transform ${isOpen ? 'rotate-180 text-[#8B85FF]' : ''}`}
        />
      </button>

      {isOpen && (
        <div
          id={`${id}-panel`}
          role="dialog"
          aria-modal="false"
          aria-labelledby={`${id}-label`}
          className="mt-2 rounded-2xl border border-white/10 bg-[#0D0D0F] p-3 shadow-[0_20px_50px_rgba(0,0,0,0.45)]"
        >
          <div
            role="slider"
            tabIndex={0}
            aria-label={`${label} saturation and brightness`}
            aria-valuemin={0}
            aria-valuemax={100}
            aria-valuenow={Math.round(hsv.s)}
            aria-valuetext={`${Math.round(hsv.s)} percent saturation, ${Math.round(hsv.v)} percent brightness`}
            onPointerDown={handleSaturationPointerDown}
            onPointerMove={handleSaturationPointerMove}
            onKeyDown={handleSaturationKeyDown}
            className="relative h-36 touch-none cursor-crosshair overflow-hidden rounded-xl outline-none ring-[#8B85FF] focus-visible:ring-2 focus-visible:ring-offset-2 focus-visible:ring-offset-[#0D0D0F]"
            style={{
              backgroundColor: `hsl(${hsv.h} 100% 50%)`,
              backgroundImage:
                'linear-gradient(to top, #000 0%, transparent 100%), linear-gradient(to right, #fff 0%, rgba(255,255,255,0) 100%)',
            }}
          >
            <span
              aria-hidden="true"
              className="pointer-events-none absolute h-4 w-4 -translate-x-1/2 -translate-y-1/2 rounded-full border-2 border-white shadow-[0_1px_5px_rgba(0,0,0,0.9)]"
              style={{ left: `${hsv.s}%`, top: `${100 - hsv.v}%`, backgroundColor: normalizedColor }}
            />
          </div>

          <div
            role="slider"
            tabIndex={0}
            aria-label={`${label} hue`}
            aria-valuemin={0}
            aria-valuemax={360}
            aria-valuenow={Math.round(hsv.h)}
            onPointerDown={handleHuePointerDown}
            onPointerMove={handleHuePointerMove}
            onKeyDown={handleHueKeyDown}
            className="relative mt-3 h-3 touch-none cursor-pointer rounded-full outline-none ring-[#8B85FF] focus-visible:ring-2 focus-visible:ring-offset-2 focus-visible:ring-offset-[#0D0D0F]"
            style={{
              background:
                'linear-gradient(to right, #FF0000, #FFFF00, #00FF00, #00FFFF, #0000FF, #FF00FF, #FF0000)',
            }}
          >
            <span
              aria-hidden="true"
              className="pointer-events-none absolute top-1/2 h-5 w-3 -translate-x-1/2 -translate-y-1/2 rounded-full border-2 border-white shadow-[0_1px_5px_rgba(0,0,0,0.8)]"
              style={{ left: `${hsv.h / 360 * 100}%`, backgroundColor: `hsl(${hsv.h} 100% 50%)` }}
            />
          </div>

          <div className="mt-4 flex items-end gap-2">
            <div className="min-w-0 flex-1">
              <label htmlFor={`${id}-hex`} className="mb-1.5 block text-[10px] font-bold uppercase tracking-wider text-gray-500">
                Hex
              </label>
              <div className="flex items-center rounded-xl border border-white/10 bg-white/[0.04] px-3 focus-within:border-[#635BFF]/70 focus-within:bg-white/[0.06]">
                <span
                  aria-hidden="true"
                  className="mr-2 h-4 w-4 shrink-0 rounded border border-white/15"
                  style={{ backgroundColor: normalizedColor }}
                />
                <input
                  id={`${id}-hex`}
                  type="text"
                  inputMode="text"
                  autoComplete="off"
                  spellCheck={false}
                  maxLength={7}
                  value={hexDraft}
                  onChange={(event) => handleHexChange(event.target.value)}
                  onBlur={() => setHexDraft(normalizedColor)}
                  className="min-w-0 flex-1 bg-transparent py-2.5 font-mono text-xs uppercase text-white outline-none"
                />
              </div>
            </div>

            {canUseEyeDropper && (
              <button
                type="button"
                onClick={handleEyeDropper}
                aria-label={`Pick ${label.toLowerCase()} from the screen`}
                title="Pick from screen"
                className="flex h-[42px] w-[42px] shrink-0 items-center justify-center rounded-xl border border-white/10 bg-white/[0.04] text-gray-400 transition hover:border-white/20 hover:bg-white/[0.08] hover:text-white focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#8B85FF]"
              >
                <Pipette className="h-4 w-4" />
              </button>
            )}
          </div>

          <div className="mt-4">
            <p className="mb-2 text-[10px] font-bold uppercase tracking-wider text-gray-500">Quick colors</p>
            <div className="grid grid-cols-10 gap-1.5">
              {swatches.map((swatch) => {
                const normalizedSwatch = normalizeHex(swatch) ?? DEFAULT_COLOR;
                const isSelected = normalizedSwatch === normalizedColor;

                return (
                  <button
                    type="button"
                    key={normalizedSwatch}
                    aria-label={`Use color ${normalizedSwatch}`}
                    aria-pressed={isSelected}
                    onClick={() => commitColor(normalizedSwatch)}
                    className="flex aspect-square items-center justify-center rounded-md border border-white/10 transition hover:scale-110 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#8B85FF]"
                    style={{ backgroundColor: normalizedSwatch }}
                  >
                    {isSelected && (
                      <Check className={`h-3.5 w-3.5 ${isLightColor(normalizedSwatch) ? 'text-black' : 'text-white'}`} />
                    )}
                  </button>
                );
              })}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
