import { useRef, useState, type KeyboardEvent } from 'react';
import {
  Gauge,
  Loader2,
  Maximize2,
  Pause,
  PictureInPicture2,
  Play,
  RotateCcw,
  Volume1,
  Volume2,
  VolumeX,
} from 'lucide-react';

type QuickLinksVideoPlayerProps = {
  src: string;
  title: string;
  onEnded?: () => void;
};

const formatTime = (seconds: number) => {
  if (!Number.isFinite(seconds) || seconds < 0) return '0:00';
  const minutes = Math.floor(seconds / 60);
  return `${minutes}:${Math.floor(seconds % 60).toString().padStart(2, '0')}`;
};

const PLAYBACK_RATES = [1, 1.25, 1.5, 2] as const;

export function QuickLinksVideoPlayer({
  src,
  title,
  onEnded,
}: QuickLinksVideoPlayerProps) {
  const shellRef = useRef<HTMLDivElement>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const [playing, setPlaying] = useState(false);
  const [buffering, setBuffering] = useState(false);
  const [duration, setDuration] = useState(0);
  const [currentTime, setCurrentTime] = useState(0);
  const [volume, setVolume] = useState(0.85);
  const [muted, setMuted] = useState(false);
  const [playbackRate, setPlaybackRate] = useState<(typeof PLAYBACK_RATES)[number]>(1);

  const togglePlayback = async () => {
    const video = videoRef.current;
    if (!video) return;
    if (video.ended) video.currentTime = 0;
    if (video.paused) {
      try {
        await video.play();
      } catch {
        setPlaying(false);
      }
      return;
    }
    video.pause();
  };

  const toggleMute = () => {
    const video = videoRef.current;
    if (!video) return;
    const nextMuted = !video.muted;
    video.muted = nextMuted;
    setMuted(nextMuted);
  };

  const changeVolume = (nextVolume: number) => {
    const video = videoRef.current;
    if (!video) return;
    video.volume = nextVolume;
    video.muted = nextVolume === 0;
    setVolume(nextVolume);
    setMuted(nextVolume === 0);
  };

  const cyclePlaybackRate = () => {
    const currentIndex = PLAYBACK_RATES.indexOf(playbackRate);
    const nextRate = PLAYBACK_RATES[(currentIndex + 1) % PLAYBACK_RATES.length];
    if (videoRef.current) videoRef.current.playbackRate = nextRate;
    setPlaybackRate(nextRate);
  };

  const enterFullscreen = async () => {
    const shell = shellRef.current;
    const video = videoRef.current;
    if (!shell || !video) return;
    if (shell.requestFullscreen) {
      await shell.requestFullscreen();
      return;
    }
    if ('webkitEnterFullscreen' in video) {
      (video as HTMLVideoElement & { webkitEnterFullscreen: () => void }).webkitEnterFullscreen();
    }
  };

  const enterPictureInPicture = async () => {
    const video = videoRef.current;
    if (!video || !document.pictureInPictureEnabled || !video.requestPictureInPicture) return;
    if (document.pictureInPictureElement) {
      await document.exitPictureInPicture();
      return;
    }
    await video.requestPictureInPicture();
  };

  const handleKeyboard = (event: KeyboardEvent<HTMLDivElement>) => {
    if (event.target instanceof HTMLInputElement || event.target instanceof HTMLButtonElement) return;
    if (event.key === ' ' || event.key.toLowerCase() === 'k') {
      event.preventDefault();
      void togglePlayback();
    } else if (event.key.toLowerCase() === 'm') {
      toggleMute();
    } else if (event.key.toLowerCase() === 'f') {
      void enterFullscreen();
    } else if (event.key === 'ArrowLeft' && videoRef.current) {
      videoRef.current.currentTime = Math.max(0, videoRef.current.currentTime - 5);
    } else if (event.key === 'ArrowRight' && videoRef.current) {
      videoRef.current.currentTime = Math.min(duration, videoRef.current.currentTime + 5);
    }
  };

  const volumeIcon = muted || volume === 0
    ? <VolumeX className="h-4 w-4" />
    : volume < 0.5
      ? <Volume1 className="h-4 w-4" />
      : <Volume2 className="h-4 w-4" />;

  return (
    <div
      ref={shellRef}
      tabIndex={0}
      onKeyDown={handleKeyboard}
      className="group relative isolate aspect-video w-full overflow-hidden rounded-[1.35rem] border border-white/10 bg-black shadow-[0_35px_90px_rgba(0,0,0,0.58),0_0_0_1px_rgba(255,255,255,0.03)] outline-none ring-[#d7ff55]/70 focus-visible:ring-2 sm:rounded-[1.75rem]"
    >
      <video
        ref={videoRef}
        src={src}
        preload="metadata"
        playsInline
        aria-label={title}
        onClick={() => void togglePlayback()}
        onDoubleClick={() => void enterFullscreen()}
        onLoadStart={() => setBuffering(true)}
        onCanPlay={() => setBuffering(false)}
        onWaiting={() => setBuffering(true)}
        onPlaying={() => {
          setBuffering(false);
          setPlaying(true);
        }}
        onPause={() => setPlaying(false)}
        onLoadedMetadata={(event) => {
          setDuration(event.currentTarget.duration);
          event.currentTarget.volume = volume;
        }}
        onDurationChange={(event) => setDuration(event.currentTarget.duration)}
        onTimeUpdate={(event) => setCurrentTime(event.currentTarget.currentTime)}
        onEnded={() => {
          setPlaying(false);
          onEnded?.();
        }}
        className="h-full w-full cursor-pointer object-contain"
      />

      <div className="pointer-events-none absolute inset-0 bg-[linear-gradient(180deg,rgba(0,0,0,.28),transparent_34%,transparent_55%,rgba(0,0,0,.9))]" />
      <div className="pointer-events-none absolute inset-0 ring-1 ring-inset ring-white/[0.08]" />

      <div className="pointer-events-none absolute inset-x-3 top-3 z-10 flex items-center justify-between gap-3 sm:inset-x-4 sm:top-4">
        <span className="max-w-[70%] truncate rounded-full border border-white/10 bg-black/40 px-3 py-1.5 text-[10px] font-bold tracking-wide text-white/75 backdrop-blur-xl">
          {title}
        </span>
        <span className="rounded-full border border-[#d7ff55]/25 bg-[#d7ff55]/10 px-2.5 py-1 text-[9px] font-black uppercase tracking-[0.16em] text-[#e5ff8e] backdrop-blur-xl">
          Original 4K
        </span>
      </div>

      {buffering && (
        <div className="pointer-events-none absolute inset-0 z-20 grid place-items-center bg-black/20">
          <Loader2 className="h-8 w-8 animate-spin text-white" />
        </div>
      )}

      {!playing && !buffering && (
        <button
          type="button"
          onClick={() => void togglePlayback()}
          aria-label={currentTime >= duration && duration > 0 ? 'Replay guide' : 'Play Quick Links guide'}
          className="absolute left-1/2 top-1/2 z-20 flex h-16 w-16 -translate-x-1/2 -translate-y-1/2 items-center justify-center rounded-full border border-white/20 bg-white text-black shadow-[0_18px_55px_rgba(0,0,0,0.55)] transition duration-300 hover:scale-105 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#d7ff55] sm:h-[4.5rem] sm:w-[4.5rem]"
        >
          {currentTime >= duration && duration > 0
            ? <RotateCcw className="h-6 w-6" />
            : <Play className="ml-1 h-6 w-6 fill-current" />}
        </button>
      )}

      <div className="absolute inset-x-2.5 bottom-2.5 z-30 rounded-2xl border border-white/10 bg-black/60 p-2 text-white shadow-2xl backdrop-blur-2xl sm:inset-x-4 sm:bottom-4 sm:p-2.5">
        <input
          type="range"
          min="0"
          max={duration || 0}
          step="0.05"
          value={Math.min(currentTime, duration || 0)}
          aria-label="Video progress"
          onChange={(event) => {
            const nextTime = Number(event.target.value);
            if (videoRef.current) videoRef.current.currentTime = nextTime;
            setCurrentTime(nextTime);
          }}
          className="block h-1.5 w-full cursor-pointer accent-[#d7ff55]"
        />

        <div className="mt-2 flex items-center gap-1 sm:gap-2">
          <button
            type="button"
            onClick={() => void togglePlayback()}
            aria-label={playing ? 'Pause guide' : 'Play guide'}
            className="flex h-9 w-9 shrink-0 items-center justify-center rounded-xl bg-white/10 transition hover:bg-white/20 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#d7ff55]"
          >
            {playing ? <Pause className="h-4 w-4 fill-current" /> : <Play className="h-4 w-4 fill-current" />}
          </button>

          <button
            type="button"
            onClick={toggleMute}
            aria-label={muted ? 'Unmute guide' : 'Mute guide'}
            className="flex h-9 w-9 shrink-0 items-center justify-center rounded-xl transition hover:bg-white/10 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#d7ff55]"
          >
            {volumeIcon}
          </button>

          <input
            type="range"
            min="0"
            max="1"
            step="0.05"
            value={muted ? 0 : volume}
            aria-label="Video volume"
            onChange={(event) => changeVolume(Number(event.target.value))}
            className="hidden h-1 w-16 cursor-pointer accent-white sm:block lg:w-20"
          />

          <span className="min-w-0 flex-1 truncate font-mono text-[9px] tabular-nums text-white/55 sm:text-[10px]">
            {formatTime(currentTime)} <span className="text-white/25">/</span> {formatTime(duration)}
          </span>

          <button
            type="button"
            onClick={cyclePlaybackRate}
            aria-label={`Playback speed ${playbackRate}x`}
            className="flex h-9 min-w-9 shrink-0 items-center justify-center gap-1 rounded-xl px-2 text-[10px] font-black transition hover:bg-white/10 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#d7ff55]"
          >
            <Gauge className="hidden h-3.5 w-3.5 sm:block" />
            {playbackRate}×
          </button>

          <button
            type="button"
            onClick={() => void enterPictureInPicture()}
            aria-label="Open picture in picture"
            className="hidden h-9 w-9 shrink-0 items-center justify-center rounded-xl transition hover:bg-white/10 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#d7ff55] sm:flex"
          >
            <PictureInPicture2 className="h-4 w-4" />
          </button>

          <button
            type="button"
            onClick={() => void enterFullscreen()}
            aria-label="Open guide fullscreen"
            className="flex h-9 w-9 shrink-0 items-center justify-center rounded-xl transition hover:bg-white/10 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#d7ff55]"
          >
            <Maximize2 className="h-4 w-4" />
          </button>
        </div>
      </div>
    </div>
  );
}
